target.css:
:root {
  --ink: #173b46;
  --paper: #fffdf6;
  --aqua: #49bfc1;
  --aqua-pale: #d9f3f1;
  --line: #a9d9d5;
}

.refill-token {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 14px;
  width: 460px;
  padding: 16px 18px;
  color: var(--ink);
  background-color: var(--paper);
  border: 2px solid var(--line);
  border-radius: 16px;
}

.token-mark {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  font-size: 27px;
  background-color: var(--aqua-pale);
  border-radius: 50%;
}

.token-details {
  flex: 1;
}

.eyebrow {
  margin: 0 0 3px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--aqua);
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.15;
}

.location {
  margin: 4px 0 0;
  font-size: 13px;
}

.credit-badge {
  padding: 6px 9px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.7px;
  color: var(--paper);
  background-color: var(--aqua);
  border-radius: 999px;
}
